package ru.mcsa.bukkit;
import java.util.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.potion.*;
public final class NativeEvents {
 private static Player BukkitPlayer(String uuid){return org.bukkit.Bukkit.getPlayer(java.util.UUID.fromString(uuid));}
 public static void dispatch(String[] a){int kind=Integer.parseInt(a[0]);String[] payload=Arrays.copyOfRange(a,1,a.length);boolean cancelled=false;
  switch(kind){
   case 12:{org.bukkit.inventory.InventoryView view=new NativeInventoryView(BukkitPlayer(payload[0]));cancelled=ChestViews.click(view,Integer.parseInt(payload[1]),Integer.parseInt(payload[2]),Integer.parseInt(payload[3]))!=0;break;}
   case 13:{org.bukkit.inventory.InventoryView view=new NativeInventoryView(BukkitPlayer(payload[0]));java.util.Set<Integer> slots=new java.util.LinkedHashSet<>();for(int i=1;i<payload.length;i++)slots.add(Integer.parseInt(payload[i]));org.bukkit.event.inventory.InventoryDragEvent event=new org.bukkit.event.inventory.InventoryDragEvent(view,view.getCursor(),slots);RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 0:{PotionEffectType type=PotionEffectType.getByName(payload[2]);if(type==null)throw new IllegalArgumentException("Неизвестный эффект");PotionEffect effect=new PotionEffect(type,Integer.parseInt(payload[3]),Integer.parseInt(payload[4]),payload[5].equals("1"),payload[6].equals("1"),payload[7].equals("1"));EntityPotionEffectEvent event=new EntityPotionEffectEvent(RemoteEntity.find(payload[0]),effect,EntityPotionEffectEvent.Action.valueOf(payload[1]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 1:{List<Entity> entities=new ArrayList<>();for(int i=1;i<payload.length;i++)entities.add(RemoteEntity.find(payload[i]));RuntimeState.fire(new org.bukkit.event.world.EntitiesLoadEvent(new RemoteWorld(Integer.parseInt(payload[0])),entities));break;}
   case 2:{CreatureSpawnEvent event=new CreatureSpawnEvent((LivingEntity)RemoteEntity.find(payload[0]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 11:{org.bukkit.event.world.GenericGameEvent event=new org.bukkit.event.world.GenericGameEvent(payload[0].isEmpty()?null:RemoteEntity.find(payload[0]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 4:{EntityTargetLivingEntityEvent event=new EntityTargetLivingEntityEvent(RemoteEntity.find(payload[0]),payload[1].isEmpty()?null:(LivingEntity)RemoteEntity.find(payload[1]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 8:case 9:{Map<LivingEntity,Double> affected=new LinkedHashMap<>();for(int i=1;i<payload.length;i+=2)affected.put((LivingEntity)RemoteEntity.find(payload[i]),Double.parseDouble(payload[i+1]));if(kind==8){PotionSplashEvent event=new PotionSplashEvent((ThrownPotion)RemoteEntity.find(payload[0]),affected);RuntimeState.fire(event);cancelled=event.isCancelled();for(int i=1;i<payload.length;i+=2)payload[i+1]=""+event.getIntensity((LivingEntity)RemoteEntity.find(payload[i]));}else {AreaEffectCloudApplyEvent event=new AreaEffectCloudApplyEvent((AreaEffectCloud)RemoteEntity.find(payload[0]),new ArrayList<>(affected.keySet()));RuntimeState.fire(event);cancelled=event.isCancelled();Set<String> kept=new HashSet<>();for(LivingEntity entity:event.getAffectedEntities()){if(!affected.containsKey(entity))throw new UnsupportedOperationException("Добавление сущности вне области облака пока не поддерживается");kept.add(entity.getUniqueId().toString());}for(int i=1;i<payload.length;i+=2)if(!kept.contains(payload[i]))payload[i+1]="0";}break;}
   case 6:{EntityCombustByEntityEvent event=new EntityCombustByEntityEvent(RemoteEntity.find(payload[1]),RemoteEntity.find(payload[0]),Float.parseFloat(payload[2]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   case 7:{List<org.bukkit.block.Block> blocks=new ArrayList<>();Map<org.bukkit.block.Block,String> original=new HashMap<>();RemoteWorld world=new RemoteWorld(Integer.parseInt(payload[1]));for(int i=2;i<payload.length;i++){String[] pos=payload[i].split(" ");org.bukkit.block.Block block=world.getBlockAt(Integer.parseInt(pos[0]),Integer.parseInt(pos[1]),Integer.parseInt(pos[2]));blocks.add(block);original.put(block,payload[i]);}EntityExplodeEvent event=new EntityExplodeEvent(RemoteEntity.find(payload[0]),blocks);RuntimeState.fire(event);cancelled=event.isCancelled();List<String> fields=new ArrayList<>();fields.add(payload[0]);fields.add(payload[1]);for(org.bukkit.block.Block block:event.blockList()){String pos=original.get(block);if(pos==null)throw new UnsupportedOperationException("Добавление блока вне области взрыва пока не поддерживается");fields.add(pos);}payload=fields.toArray(new String[0]);break;}
   case 5:{EntityShootBowEvent event=new EntityShootBowEvent((LivingEntity)RemoteEntity.find(payload[0]),null,RemoteEntity.find(payload[1]),Float.parseFloat(payload[2]));RuntimeState.fire(event);cancelled=event.isCancelled();break;}
   default:throw new IllegalArgumentException("Неизвестное нативное событие: "+kind);
  }
  StringBuilder result=new StringBuilder(cancelled?"1\n":"0\n");for(String field:payload){if(field.indexOf('\n')>=0)throw new IllegalArgumentException("Перевод строки в поле события запрещён");result.append(field).append('\n');}Host.call(22,result.toString());
 }
}
